const std = @import("std");

pub fn truncate(phrase: []const u8) []const u8 {
    // Parse UTF-8 to get codepoints
    const codepoints = try std.mem.parseUtf8(phrase);
    // Allocate enough space for 5 codepoints (max 4 bytes each)
    const max_bytes = 5 * 4;
    const buffer = try std.heap.page_allocator.alloc(u8, max_bytes);
    // Copy up to 5 codepoints
    var written: usize = 0;
    var i: usize = 0;
    for (codepoints) |cp, _| {
        if (i >= 5) {
            break;
        }
        const bytes = @utf8FromCodepoint(cp);
        // Copy bytes into buffer
        buffer[written..written + bytes.len] = bytes;
        written += bytes.len;
        i += 1;
    }
    // Return a slice that represents the truncated result
    return buffer[0..written];
}

